#pragma once

// Nextendo patch files that the Hub carries in its romfs (list: kPatchFiles, generated by tools/nextendo/sync.py).
// Pure rules, no I/O; host test tests/test_nextendo_patches.cpp.
// Required Notice: Copyright 2026 Nextendo Network (PolyForm Shield 1.0.0, assets/romfs/nextendo/LICENSE.md)

#include "nextendo_snapshot.hpp"

#include <array>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace sphaira::nextendo {

using BuildId = std::array<std::uint8_t, 0x20>;

// Every patch folder the Hub writes starts with this, so all of them can be found (and moved by Semi-stock)
// without a list. Folders of Kefir or of a standalone Prelude never do.
inline constexpr std::string_view kPatchPrefix = "nextendo_";
inline constexpr std::string_view kSslFolder = "atmosphere/exefs_patches/nextendo_disable_ca_verification/";

// "nextendo_*" folder names that kPatchFiles has directly under `root` ("atmosphere/exefs_patches/").
inline auto ShippedFolders(std::string_view root) -> std::vector<std::string> {
    std::vector<std::string> out;
    for (const auto& f : kPatchFiles) {
        const std::string_view path = f.path;
        if (path.substr(0, root.size()) != root) {
            continue;
        }
        const auto rest = path.substr(root.size());
        const std::string name{rest.substr(0, rest.find('/'))};
        if (name.rfind(kPatchPrefix, 0) == 0 && (out.empty() || out.back() != name)) {
            out.push_back(name); // kPatchFiles is sorted, so equal names are neighbours
        }
    }
    return out;
}

// An IPS name is the build ID in hex (40 or 64 digits). Atmosphere reads it into a zero-padded 0x20-byte ID and
// compares it with the module's ID, so the same is done here.
inline auto ParseBuildId(std::string_view hex) -> std::optional<BuildId> {
    if (hex.empty() || hex.size() > 64 || hex.size() % 2) {
        return std::nullopt;
    }
    const auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    BuildId id{};
    for (std::size_t i = 0; i < hex.size(); i += 2) {
        const int hi = nibble(hex[i]);
        const int lo = nibble(hex[i + 1]);
        if (hi < 0 || lo < 0) {
            return std::nullopt;
        }
        id[i / 2] = static_cast<std::uint8_t>(hi * 16 + lo);
    }
    return id;
}

// True when one of the modules (the ssl process) has an IPS in the shipped ssl folder: Nextendo TLS works on this firmware.
inline auto SslPatched(const std::vector<BuildId>& modules) -> bool {
    for (const auto& f : kPatchFiles) {
        std::string_view path = f.path;
        if (path.substr(0, kSslFolder.size()) != kSslFolder || path.size() < kSslFolder.size() + 4) {
            continue;
        }
        const auto id = ParseBuildId(path.substr(kSslFolder.size(), path.size() - kSslFolder.size() - 4));
        for (const auto& m : modules) {
            if (id && *id == m) {
                return true;
            }
        }
    }
    return false;
}

inline auto BuildIdHex(const BuildId& id) -> std::string {
    static constexpr char kHex[] = "0123456789ABCDEF";
    std::string out;
    for (std::size_t i = 0; i < 20; i++) { // the part that is not zero padding
        out += kHex[id[i] >> 4];
        out += kHex[id[i] & 0xF];
    }
    return out;
}

} // namespace sphaira::nextendo
